<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/database.php';
function team_uuid():string{$d=random_bytes(16);$d[6]=chr((ord($d[6])&15)|64);$d[8]=chr((ord($d[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($d),4));}
$pdo=null;$err=null;$notice=null;$roles=[];$members=[];
$positionOptions=['Founder & CEO','COO','CTO','CFO','Head','Manager','Lead','Specialist','Coordinator','Associate','Intern'];
$departmentOptions=['Executive','Commercial','Operations','Product','Engineering','Customer Success','Support','Marketing','Finance','Legal','People'];
try{$pdo=oplen_pdo();$roles=$pdo->query("SELECT id,code,name FROM admin_roles ORDER BY id")->fetchAll();}catch(Throwable $e){$err=$e->getMessage();}
$action=(string)($_GET['action']??'');$id=trim((string)($_GET['id']??''));
if($pdo && $_SERVER['REQUEST_METHOD']==='POST'){
  $op=(string)($_POST['op']??'save');$memberId=trim((string)($_POST['id']??''));
  try{
    if($op==='status' && $memberId!==''){
      $status=in_array($_POST['status']??'', ['active','inactive','suspended'],true)?$_POST['status']:'active';
      $pdo->beginTransaction();$q=$pdo->prepare("UPDATE team_members SET status=? WHERE id=?");$q->execute([$status,$memberId]);
      if($status!=='active'){$q=$pdo->prepare("UPDATE admin_accounts SET status='suspended' WHERE team_member_id=? AND status<>'disabled'");$q->execute([$memberId]);}
      $pdo->commit();header('Location: '.page_url('team').'&id='.rawurlencode($memberId).'&saved=1');exit;
    }
    $first=trim((string)($_POST['first_name']??''));$last=trim((string)($_POST['last_name']??''));$email=strtolower(trim((string)($_POST['work_email']??'')));$position=trim((string)($_POST['position_title']??''));$department=trim((string)($_POST['department']??''));$status=in_array($_POST['status']??'', ['active','inactive','suspended'],true)?$_POST['status']:'active';
    if($first===''||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Name and a valid work email are required.');
    if($position!==''&&!in_array($position,$positionOptions,true))throw new RuntimeException('Choose a valid position.');
    if($department!==''&&!in_array($department,$departmentOptions,true))throw new RuntimeException('Choose a valid department.');
    $pdo->beginTransaction();
    if($memberId===''){$memberId=team_uuid();$q=$pdo->prepare("INSERT INTO team_members(id,first_name,last_name,work_email,position_title,department,status) VALUES(?,?,?,?,?,?,?)");$q->execute([$memberId,$first,$last?:null,$email,$position?:null,$department?:null,$status]);}
    else{$q=$pdo->prepare("UPDATE team_members SET first_name=?,last_name=?,work_email=?,position_title=?,department=?,status=? WHERE id=?");$q->execute([$first,$last?:null,$email,$position?:null,$department?:null,$status,$memberId]);}
    $q=$pdo->prepare("SELECT id FROM admin_accounts WHERE team_member_id=? LIMIT 1");$q->execute([$memberId]);$adminId=$q->fetchColumn()?:null;
    $wantsAdmin=isset($_POST['has_admin']);$roleId=(int)($_POST['role_id']??0);$adminStatus=in_array($_POST['admin_status']??'', ['invited','active','suspended','disabled'],true)?$_POST['admin_status']:'active';$password=(string)($_POST['password']??'');
    if($wantsAdmin){if(!$roleId)throw new RuntimeException('Choose an Admin role.');if(!$adminId){if(strlen($password)<8)throw new RuntimeException('A temporary password of at least 8 characters is required for a new Admin account.');$adminId=team_uuid();$q=$pdo->prepare("INSERT INTO admin_accounts(id,team_member_id,email,password_hash,role_id,status,password_changed_at) VALUES(?,?,?,?,?,?,NOW())");$q->execute([$adminId,$memberId,$email,password_hash($password,PASSWORD_DEFAULT),$roleId,$adminStatus]);}else{$sql="UPDATE admin_accounts SET email=?,role_id=?,status=?";$args=[$email,$roleId,$adminStatus];if($password!==''){if(strlen($password)<8)throw new RuntimeException('Password must be at least 8 characters.');$sql.=",password_hash=?,password_changed_at=NOW()";$args[]=password_hash($password,PASSWORD_DEFAULT);}$sql.=" WHERE id=?";$args[]=$adminId;$q=$pdo->prepare($sql);$q->execute($args);}}
    elseif($adminId){$q=$pdo->prepare("UPDATE admin_accounts SET status='disabled' WHERE id=?");$q->execute([$adminId]);}
    $pdo->commit();header('Location: '.page_url('team').'&id='.rawurlencode($memberId).'&saved=1');exit;
  }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err=$e->getMessage();$action='edit';$id=$memberId;}
}
if(isset($_GET['saved']))$notice='Changes saved.';
$selected=null;
if($pdo&&$id!==''){$q=$pdo->prepare("SELECT t.*,a.id admin_id,a.email admin_email,a.role_id,a.status admin_status,a.last_login_at,r.name role_name FROM team_members t LEFT JOIN admin_accounts a ON a.team_member_id=t.id LEFT JOIN admin_roles r ON r.id=a.role_id WHERE t.id=? LIMIT 1");$q->execute([$id]);$selected=$q->fetch()?:null;if($selected)$action='edit';}
if($pdo){try{$members=$pdo->query("SELECT t.id,t.first_name,t.last_name,t.work_email,t.position_title,t.department,t.status,a.email admin_email,a.status admin_status,a.last_login_at,r.name role_name FROM team_members t LEFT JOIN admin_accounts a ON a.team_member_id=t.id LEFT JOIN admin_roles r ON r.id=a.role_id ORDER BY FIELD(t.status,'active','inactive','suspended'),t.first_name,t.last_name")->fetchAll();}catch(Throwable $e){$err=$e->getMessage();}}
if($action==='new'||$action==='edit'){
$m=$selected?:['id'=>'','first_name'=>'','last_name'=>'','work_email'=>'','position_title'=>'','department'=>'','status'=>'active','admin_id'=>null,'role_id'=>'','admin_status'=>'active','last_login_at'=>null];?>
<header class="page-head"><div><span class="eyebrow">OPLEN / INTERNAL TEAM</span><h1><?= $m['id']?'Team member':'Add member' ?></h1><p><?= $m['id']?'Manage collaborator profile and Admin access.':'Create an internal Oplen collaborator.' ?></p></div><a class="ghostbtn" href="<?=page_url('team')?>">← Team</a></header>
<?php if($err):?><div class="health-error"><?=e($err)?></div><?php endif?><?php if($notice):?><div class="notice-success"><?=e($notice)?></div><?php endif?>
<form method="post" class="team-layout"><input type="hidden" name="op" value="save"><input type="hidden" name="id" value="<?=e($m['id'])?>">
<section class="panel"><span class="eyebrow">PROFILE</span><h2>Collaborator information</h2><div class="form-grid"><label>First name<input name="first_name" required value="<?=e($m['first_name'])?>"></label><label>Last name<input name="last_name" value="<?=e($m['last_name']??'')?>"></label><label class="span-2">Work email<input type="email" name="work_email" required value="<?=e($m['work_email'])?>"></label><label>Position<select name="position_title"><option value="">Choose position</option><?php foreach($positionOptions as $option):?><option value="<?=e($option)?>" <?=($m['position_title']??'')===$option?'selected':''?>><?=e($option)?></option><?php endforeach?></select></label><label>Department<select name="department"><option value="">Choose department</option><?php foreach($departmentOptions as $option):?><option value="<?=e($option)?>" <?=($m['department']??'')===$option?'selected':''?>><?=e($option)?></option><?php endforeach?></select></label><label>Status<select name="status"><?php foreach(['active'=>'Active','inactive'=>'Inactive','suspended'=>'Suspended'] as $k=>$v):?><option value="<?=$k?>" <?=$m['status']===$k?'selected':''?>><?=$v?></option><?php endforeach?></select></label></div></section>
<section class="panel"><span class="eyebrow">ADMIN ACCESS</span><h2>Backoffice account</h2><label class="check-row"><input type="checkbox" name="has_admin" value="1" <?=!empty($m['admin_id'])&&($m['admin_status']??'')!=='disabled'?'checked':''?>><span><strong>Give this member Admin access</strong><small>Internal Admin access is separate from customer accounts.</small></span></label><div class="form-grid admin-fields"><label>Role<select name="role_id"><option value="">Choose role</option><?php foreach($roles as $r):?><option value="<?=e((string)$r['id'])?>" <?=((string)($m['role_id']??'')===(string)$r['id'])?'selected':''?>><?=e($r['name'])?></option><?php endforeach?></select></label><label>Account status<select name="admin_status"><?php foreach(['active'=>'Active','invited'=>'Invited','suspended'=>'Suspended','disabled'=>'Disabled'] as $k=>$v):?><option value="<?=$k?>" <?=($m['admin_status']??'active')===$k?'selected':''?>><?=$v?></option><?php endforeach?></select></label><label class="span-2">Temporary / new password<input type="password" name="password" autocomplete="new-password" placeholder="<?=!empty($m['admin_id'])?'Leave blank to keep current password':'Minimum 8 characters'?>"></label></div><?php if(!empty($m['last_login_at'])):?><p class="muted">Last Admin access: <?=e(date('d M Y · H:i',strtotime($m['last_login_at'])))?></p><?php endif?></section>
<div class="form-actions"><a class="ghostbtn" href="<?=page_url('team')?>">Cancel</a><button class="button" type="submit">Save member</button></div></form>
<?php if($m['id']):?><section class="danger-zone"><div><strong>Access control</strong><p>Suspending a member also suspends their Admin account.</p></div><form method="post"><input type="hidden" name="op" value="status"><input type="hidden" name="id" value="<?=e($m['id'])?>"><input type="hidden" name="status" value="<?=$m['status']==='active'?'suspended':'active'?>"><button class="danger-button" type="submit"><?=$m['status']==='active'?'Suspend member':'Reactivate member'?></button></form></section><?php endif?>
<?php return;}?>
<header class="page-head"><div><span class="eyebrow">OPLEN</span><h1>Internal team</h1><p>People who operate Oplen and their administrative access.</p></div><a class="button" href="<?= page_url('team') ?>&action=new">+ Add member</a></header>
<?php if($err):?><div class="health-error"><?=e($err)?></div><?php endif?><?php if($notice):?><div class="notice-success"><?=e($notice)?></div><?php endif?>
<section class="metrics"><article><span>Team members</span><strong><?=count($members)?></strong><small>Internal people</small></article><article><span>Active</span><strong><?=count(array_filter($members,fn($m)=>$m['status']==='active'))?></strong><small>Active collaborators</small></article><article><span>Admin accounts</span><strong><?=count(array_filter($members,fn($m)=>!empty($m['admin_email'])&&$m['admin_status']!=='disabled'))?></strong><small>Can access Admin</small></article><article><span>Suspended</span><strong><?=count(array_filter($members,fn($m)=>in_array($m['status'],['inactive','suspended'],true)))?></strong><small>Without active status</small></article></section>
<section class="panel table-panel"><div class="table-head"><div><h2>Team members</h2><p>Click a collaborator to manage profile and access.</p></div><span><?=count($members)?> members</span></div><?php if(!$members):?><div class="empty large"><strong>No internal team members yet.</strong><p>Create the first collaborator to begin managing Oplen's internal access.</p></div><?php else:?><div style="overflow:auto"><table class="click-table"><thead><tr><th>Member</th><th>Position</th><th>Department</th><th>Admin role</th><th>Admin account</th><th>Status</th><th>Last access</th></tr></thead><tbody><?php foreach($members as $m):?><tr onclick="location.href='<?=page_url('team')?>&id=<?=rawurlencode($m['id'])?>'"><td><strong><?=e(trim($m['first_name'].' '.$m['last_name']))?></strong><br><span class="muted"><?=e($m['work_email'])?></span></td><td><?=e($m['position_title']?:'—')?></td><td><?=e($m['department']?:'—')?></td><td><?=e($m['role_name']?:'—')?></td><td><?= $m['admin_email'] ? '<span class="stage-pill '.($m['admin_status']==='active'?'stage-new':'').'">'.e($m['admin_status']).'</span>' : '<span class="muted">No account</span>' ?></td><td><?=e(ucfirst($m['status']))?></td><td><?=e($m['last_login_at']?date('d M Y · H:i',strtotime($m['last_login_at'])):'Never')?></td></tr><?php endforeach?></tbody></table></div><?php endif?></section>